import pandas as pd

turns = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=8, usecols='C:J')
turns = turns[turns['Turn number'].notna()].copy()
for c in turns.columns:
    turns[c] = turns[c].astype(int)

categories = ['High and Often','Summation','Highs and Lows','Only two numbers','All the numbers','Ordered subset of four']


def turn_scores(rolls):
    mx = max(rolls)
    mn = min(rolls)
    high_often = mx * rolls.count(mx)
    summation = sum(rolls)
    highs_lows = mx * mn * (mx - mn)
    only_two = 30 if len(set(rolls)) == 2 else None
    all_numbers = 40 if set(rolls) == {1,2,3,4,5,6} else None
    ordered = None
    for i in range(3):
        window = rolls[i:i+4]
        diffs = [window[j+1]-window[j] for j in range(3)]
        if all(d==1 for d in diffs) or all(d==-1 for d in diffs):
            ordered = 50
            break
    return [high_often, summation, highs_lows, only_two, all_numbers, ordered]

scores = []
for _, row in turns.iterrows():
    rolls = [row[f'Roll {i}'] for i in range(1,7)]
    scores.append(turn_scores(rolls))

scores_df = pd.DataFrame(scores, columns=categories)
turns = pd.concat([turns.reset_index(drop=True), scores_df], axis=1)


def best_game_score(t1_scores, t2_scores):
    best = -10**9
    for i, s1 in enumerate(t1_scores):
        if s1 is None:
            continue
        for j, s2 in enumerate(t2_scores):
            if i==j or s2 is None:
                continue
            total = s1 + s2
            if total > best:
                best = total
    return best

best_scores = {}
for game, grp in turns.groupby('Game number'):
    if len(grp) != 2:
        best_scores[game] = None
        continue
    grp = grp.sort_values('Turn number')
    t1 = grp.iloc[0][categories].tolist()
    t2 = grp.iloc[1][categories].tolist()
    best_scores[game] = best_game_score(t1, t2)

# scenario A: skip matches with missing scores
p1 = p2 = 0
skipped = 0
for g in range(1, max(best_scores.keys())+1, 2):
    s1 = best_scores.get(g)
    s2 = best_scores.get(g+1)
    if s1 is None or s2 is None:
        skipped += 1
        continue
    if s1 > s2:
        p1 += 1
    elif s2 > s1:
        p2 += 1

diff_skip = p1 - p2

# scenario B: treat missing as 0
p1b = p2b = 0
for g in range(1, max(best_scores.keys())+1, 2):
    s1 = best_scores.get(g)
    s2 = best_scores.get(g+1)
    if s1 is None:
        s1 = 0
    if s2 is None:
        s2 = 0
    if s1 > s2:
        p1b += 1
    elif s2 > s1:
        p2b += 1

print('scenario A diff', diff_skip, 'p1', p1, 'p2', p2, 'skipped', skipped)
print('scenario B diff', p1b-p2b, 'p1', p1b, 'p2', p2b)

# also check if any ties

ties=0
for g in range(1, max(best_scores.keys())+1, 2):
    s1 = best_scores.get(g)
    s2 = best_scores.get(g+1)
    if s1 is None or s2 is None:
        continue
    if s1 == s2:
        ties += 1
print('ties', ties)
